function restoreProperty(object, name, descriptor) {
  if (descriptor === undefined) delete object[name];
  else Object.defineProperty(object, name, descriptor);
}

function poisonScalars(state, enabledName) {
  const enabledDescriptor = Object.getOwnPropertyDescriptor(state, enabledName);
  const highWaterMarkDescriptor = Object.getOwnPropertyDescriptor(
    state,
    "highWaterMark",
  );
  let enabled = state[enabledName];
  let highWaterMark = state.highWaterMark;
  let enabledReads = 0;
  let highWaterMarkReads = 0;

  Object.defineProperty(state, enabledName, {
    configurable: true,
    enumerable: false,
    get() {
      enabledReads++;
      return enabled;
    },
    set(value) {
      enabled = value;
    },
  });
  Object.defineProperty(state, "highWaterMark", {
    configurable: true,
    enumerable: true,
    get() {
      highWaterMarkReads++;
      return highWaterMark;
    },
    set(value) {
      highWaterMark = value;
    },
  });

  return {
    outcome() {
      return enabledReads === 0 && highWaterMarkReads === 0
        ? "CLEAN"
        : `TOUCHED:${enabledReads}:${highWaterMarkReads}`;
    },
    restore() {
      restoreProperty(state, enabledName, enabledDescriptor);
      restoreProperty(state, "highWaterMark", highWaterMarkDescriptor);
    },
  };
}

exports.poisonReadableScalars = function poisonReadableScalars(stream) {
  return poisonScalars(stream._readableState, "readable");
};

exports.poisonWritableScalars = function poisonWritableScalars(stream) {
  return poisonScalars(stream._writableState, "writable");
};
